import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import './AdminDashboard.css';

const AdminDashboard = ({ user, onLogout }) => {
  const [activeTab, setActiveTab] = useState('activities');
  const navigate = useNavigate();

  const activities = [];
  const logs = [];
  const alerts = [];

  const renderTabContent = () => {
    let items = [];
    if (activeTab === 'activities') items = activities;
    else if (activeTab === 'logs') items = logs;
    else if (activeTab === 'alerts') items = alerts;

    if (items.length === 0) {
      return (
        <div style={{ 
          padding: '40px', 
          textAlign: 'center', 
          color: '#999',
          backgroundColor: '#f9f9f9',
          borderRadius: '8px',
          border: '1px dashed #ddd'
        }}>
          <p style={{ fontSize: '16px', margin: 0 }}>📊 Data will be populated from database</p>
          <p style={{ fontSize: '12px', color: '#bbb', marginTop: '8px' }}>Ready for database integration</p>
        </div>
      );
    }

    return (
      <ul className="activity-list">
        {items.map((item, index) => (
          <li key={index} className="activity-item">
            <span>{item.text}</span>
            <span className="activity-time">{item.time}</span>
          </li>
        ))}
      </ul>
    );
  };

  return (
    <div className="admin-container">
      <Navbar user={user} onLogout={onLogout} />
      
      <div className="container">
        <div className="section-header">
          <h1 className="section-title">Admin Dashboard</h1>
          <p className="section-subtitle">System Administration & Management</p>
        </div>

        <div className="stats-container">
          <div className="stat-card">
            <div className="stat-label">Total Employees</div>
            <div className="stat-value">--</div>
            <div className="stat-icon">👥</div>
          </div>
          <div className="stat-card">
            <div className="stat-label">Present Today</div>
            <div className="stat-value green">--</div>
            <div className="stat-icon">•</div>
          </div>
          <div className="stat-card">
            <div className="stat-label">On Leave</div>
            <div className="stat-value orange">--</div>
            <div className="stat-icon">□</div>
          </div>
          <div className="stat-card">
            <div className="stat-label">System Users</div>
            <div className="stat-value">--</div>
            <div className="stat-icon">👤</div>
          </div>
        </div>

        <div className="records-section">
          <div className="records-header">
            <h2 className="records-title">Admin Controls & Management</h2>
          </div>

          <div className="tab-buttons">
            <button 
              className={`tab-btn ${activeTab === 'activities' ? 'active' : ''}`}
              onClick={() => setActiveTab('activities')}
            >
              Recent Activities
            </button>
            <button 
              className={`tab-btn ${activeTab === 'logs' ? 'active' : ''}`}
              onClick={() => setActiveTab('logs')}
            >
              System Logs
            </button>
            <button 
              className={`tab-btn ${activeTab === 'alerts' ? 'active' : ''}`}
              onClick={() => setActiveTab('alerts')}
            >
              Alerts
            </button>
          </div>

          {renderTabContent()}
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
